pragma solidity ^0.8.24;

import "@openzeppelin/contracts/utils/Strings.sol";
import "./libraries/StonkBrokerTraitsV6Proposal.sol";

/// @notice Preview-only renderer for proposed V6 collection.
/// V6 proposal art — Devil/Bull horns, Gold Tooth mouth (Smirk + 1px).
contract StonkBrokerSvgRendererV6Proposal {
    using Strings for uint256;

    function traitSignatureFromSeed(uint256 seed) external pure returns (bytes32) {
        return StonkBrokerTraitsV6Proposal.traitSignature(seed);
    }

    function decodeTraits(uint256 seed) external pure returns (StonkBrokerTraitsV6Proposal.Traits memory) {
        return StonkBrokerTraitsV6Proposal.decode(seed);
    }

    function candidateTraitSeed(uint256 tokenId, uint256 attempt) external pure returns (uint256) {
        return StonkBrokerTraitsV6Proposal.candidateSeed(tokenId, attempt);
    }

    /// @notice Export individual art layers as standalone SVGs for off-chain QA review.
    function renderLayers(uint256 tokenId, uint256 traitSeed)
        external
        pure
        returns (
            string memory background,
            string memory body,
            string memory skin,
            string memory hair,
            string memory eyes,
            string memory mouth,
            string memory faceAccessory,
            string memory brokerBadge,
            string memory composite
        )
    {
        composite = renderSvg(tokenId, traitSeed);

        StonkBrokerTraitsV6Proposal.Traits memory t = StonkBrokerTraitsV6Proposal.decode(traitSeed);
        string memory bgHex = _hex(_pickBackground(t.background));
        string memory tieHex = _hex(_pickTie(t.tie));
        string memory skinHex = _hex(_pickSkin(t.skin));
        string memory hairHex = _hex(_pickHairColor(t.hairColor));

        background = _wrapLayer(
            string(abi.encodePacked('<rect width="24" height="24" fill="#', bgHex, '"/>')), false
        );
        body = _wrapLayer(_bodyForSuit(t.suit, tieHex, t.neckwear), true);
        skin = _wrapLayer(_svgSkinNeck(skinHex, t.skin, t.hairStyle), true);
        hair = _wrapLayer(_svgHair(t.hairStyle, hairHex), true);
        eyes = _wrapLayer(_eyeMarkup(t.eyeColor, _noseMarkup(t.noseColor)), true);
        mouth = _wrapLayer(_renderMouth(t.mouth), true);
        faceAccessory = _wrapLayer(_renderFaceAccessoryForHair(t.faceAccessory, t.hairStyle), true);
        brokerBadge = _wrapLayer(_renderBrokerBadge(t.brokerBadge), true);
    }

    function renderSvg(uint256 /* tokenId */, uint256 traitSeed) public pure returns (string memory) {
        StonkBrokerTraitsV6Proposal.Traits memory t = StonkBrokerTraitsV6Proposal.decode(traitSeed);
        string memory bg = _hex(_pickBackground(t.background));
        string memory tie = _hex(_pickTie(t.tie));
        string memory skin = _hex(_pickSkin(t.skin));
        string memory hair = _hex(_pickHairColor(t.hairColor));

        return
            string(
                abi.encodePacked(
                    _svgHead(bg),
                    _svgFace(t, skin, hair, ""),
                    _bodyForSuit(t.suit, tie, t.neckwear),
                    _renderPocketSquare(t.pocketSquare),
                    _renderFaceAccessoryForHair(t.faceAccessory, t.hairStyle),
                    _renderBrokerBadge(t.brokerBadge),
                    "</svg>"
                )
            );
    }

    /// @notice Attributes with a "None" value are omitted entirely rather than listed —
    /// tokens without that trait simply carry one fewer attribute (cleaner rarity tooling).
    function buildVisualAttributes(uint256 /* tokenId */, uint256 traitSeed) external pure returns (string memory) {
        StonkBrokerTraitsV6Proposal.Traits memory t = StonkBrokerTraitsV6Proposal.decode(traitSeed);
        return
            string(
                abi.encodePacked(
                    '{"trait_type":"Background","value":"',
                    backgroundName(t.background),
                    '"}',
                    _attr("Skin", StonkBrokerTraitsV6Proposal.skinName(t.skin)),
                    _attr("Hair Style", StonkBrokerTraitsV6Proposal.hairStyleName(t.hairStyle)),
                    _attr("Hair Color", StonkBrokerTraitsV6Proposal.hairColorNameForMetadata(t.hairStyle, t.hairColor)),
                    _attr("Eyes", StonkBrokerTraitsV6Proposal.eyeColorName(t.eyeColor)),
                    _attr("Nose", StonkBrokerTraitsV6Proposal.noseColorName(t.noseColor)),
                    _attr("Mouth", StonkBrokerTraitsV6Proposal.mouthName(t.mouth)),
                    _attr("Suit", StonkBrokerTraitsV6Proposal.suitName(t.suit)),
                    _attr("Tie", StonkBrokerTraitsV6Proposal.tieName(t.tie)),
                    _attr("Neckwear", StonkBrokerTraitsV6Proposal.neckwearName(t.neckwear)),
                    _attr("Face Accessory", StonkBrokerTraitsV6Proposal.faceAccessoryName(t.faceAccessory)),
                    _attr("Broker Badge", StonkBrokerTraitsV6Proposal.brokerBadgeName(t.brokerBadge)),
                    _attr("Pocket Square", StonkBrokerTraitsV6Proposal.pocketSquareName(t.pocketSquare))
                )
            );
    }

    function _attr(string memory traitType, string memory value) internal pure returns (string memory) {
        if (keccak256(bytes(value)) == keccak256(bytes("None"))) return "";
        return string(abi.encodePacked(',{"trait_type":"', traitType, '","value":"', value, '"}'));
    }

    function backgroundName(uint8 idx) internal pure returns (string memory) {
        if (idx == 0) return "Sky Blue";
        if (idx == 1) return "Light Blue";
        if (idx == 2) return "Pale Blue";
        if (idx == 3) return "Tan";
        if (idx == 4) return "Slate";
        if (idx == 5) return "Steel";
        if (idx == 6) return "Trading Floor Green";
        return "Bloomberg Orange";
    }

    function _svgHead(string memory bg) internal pure returns (string memory) {
        return
            string(
                abi.encodePacked(
                    '<svg xmlns="http://www.w3.org/2000/svg" shape-rendering="crispEdges" viewBox="0 0 24 24" width="720" height="720"><rect width="24" height="24" fill="#',
                    bg,
                    '"/>'
