        // 20 Black Monocle — declined
        return "";
    }

    /// @notice Banded Frameless frames + hairstyle-aware temple bands so the bands
    /// always stop exactly at the hairline instead of floating past a narrower head.
    /// bandMode: 0 = default (hair at x=6/x=17), 1 = Short Crop (hair at x=7/x=16),
    /// 2 = no side hair to meet (Bald / Rainbow Afro) — frames only, no temple bands.
    /// col: stroke/fill hex without '#' — "d8e1ea" silver (idx 19) or "f5d36b" gold (idx 21).
    function _svgBandedFrameless(uint8 bandMode, string memory col) internal pure returns (string memory) {
        string memory frames = string(
            abi.encodePacked(
                '<rect x="8" y="7" width="3" height="3" fill="none" stroke="#',
                col,
                '" stroke-width="0.4"/>',
                '<rect x="13" y="7" width="3" height="3" fill="none" stroke="#',
                col,
                '" stroke-width="0.4"/>',
                '<rect x="11" y="8" width="2" height="1" fill="#',
                col,
                '"/>'
            )
        );
        if (bandMode == 2) return frames;
        if (bandMode == 1) {
            // Short Crop — only 1px of skin between lens and hair; band ends flush with hair.
            return
                string(
                    abi.encodePacked(
                        frames,
                        '<rect x="7" y="8" width="1" height="1" fill="#',
                        col,
                        '"/><rect x="16" y="8" width="1" height="1" fill="#',
                        col,
                        '"/>'
                    )
                );
        }
        return
            string(
                abi.encodePacked(
                    frames,
                    '<rect x="6" y="8" width="2" height="1" fill="#',
                    col,
                    '"/><rect x="16" y="8" width="2" height="1" fill="#',
                    col,
                    '"/>'
                )
            );
    }

    function _renderFaceAccessoryForHair(uint8 acc, uint8 hairStyle) internal pure returns (string memory) {
        if (acc == 9 && hairStyle == 6) return _svgCrownOnBald();
        if (acc == 9 && hairStyle == 7) return _svgCrownOnAfro();
        if (acc == 19 || acc == 21) {
            string memory col = acc == 21 ? "f5d36b" : "d8e1ea";
            if (hairStyle == 3) return _svgBandedFrameless(1, col); // Short Crop
            if (hairStyle == 6 || hairStyle == 7) return _svgBandedFrameless(2, col); // Bald / Rainbow Afro
        }
        return _renderFaceAccessory(acc);
    }

    function _renderBrokerBadge(uint8 badge) internal pure returns (string memory) {
        if (badge == 0) return "";
        // Lapel pin — outer chest, clear of the tie knot (was x=14 next to tie)
        if (badge == 1) {
            return '<rect x="16" y="20" width="2" height="2" fill="#24a148"/><rect x="16" y="20" width="2" height="1" fill="#86efac"/>';
        }
        if (badge == 2) {
            return '<rect x="16" y="20" width="2" height="2" fill="#2b3fd1"/><rect x="17" y="20" width="1" height="1" fill="#8fb8ff"/>';
        }
        // Diamond Hands — facet highlight
        return '<rect x="16" y="20" width="1" height="1" fill="#a8f7ff"/><rect x="17" y="20" width="1" height="1" fill="#00e5ff"/><rect x="16" y="21" width="2" height="1" fill="#00b8cc"/>';
    }

    function _renderPocketSquare(uint8 sq) internal pure returns (string memory) {
        if (sq == 0) return "";
        string memory tip;
        string memory fold;
        if (sq == 1) {
            tip = "f5f0e6";
            fold = "e8dcc8";
        } else if (sq == 2) {
            tip = "ffffff";
            fold = "d8dce3";
        } else {
            tip = "f5d36b";
            fold = "e9bf52";
        }
        // Complete 2×2 breast pocket — mid-jacket (y=21–22), tip + fold row
        return
            string(
                abi.encodePacked(
                    '<rect x="6" y="21" width="2" height="1" fill="#',
                    tip,
                    '"/><rect x="6" y="22" width="2" height="1" fill="#',
                    fold,
                    '"/>'
                )
            );
    }

