    /// @notice Crown variants for museum review. `bald` drops silhouette +1px.
    /// 0–6 original pack · 10–16 centered pack (hair-aligned x=7..16, ruby options)
    function _svgCrownVariant(uint8 v, bool bald) internal pure returns (string memory) {
        if (v >= 10) return _svgCrownCentered(v - 10, bald);
        string memory y0 = bald ? "1" : "0";
        string memory y1 = bald ? "2" : "1";
        string memory y2 = bald ? "3" : "2";
        if (v == 1) {
            // Five Peak — wider royal band, five tips centered on x=12
            return
                string(
                    abi.encodePacked(
                        _crownPx("8", y0, "ffe08a"),
                        _crownPx("10", y0, "ffe08a"),
                        _crownPx("12", y0, "ffe08a"),
                        _crownPx("14", y0, "ffe08a"),
                        _crownPx("16", y0, "ffe08a"),
                        _crownBar("7", y1, "11", "f5d36b"),
                        _crownBar("8", y2, "9", "e9bf52")
                    )
                );
        }
        if (v == 2) {
            // Tiara — lighter, narrower band, three delicate tips
            return
                string(
                    abi.encodePacked(
                        _crownPx("9", y0, "ffe08a"),
                        _crownPx("12", y0, "fff6c8"),
                        _crownPx("15", y0, "ffe08a"),
                        _crownBar("9", y1, "7", "f5d36b"),
                        _crownBar("10", y2, "5", "e9bf52")
                    )
                );
        }
        if (v == 3) {
            // Ruby Peak — classic tri with blood-ruby center tip (echo Devil Horn tip)
            return
                string(
                    abi.encodePacked(
                        _crownPx("9", y0, "ffe08a"),
                        _crownPx("12", y0, "c62828"),
                        _crownPx("15", y0, "ffe08a"),
                        _crownBar("8", y1, "9", "f5d36b"),
                        _crownPx("12", y1, "ffe08a"),
                        _crownBar("9", y2, "7", "e9bf52")
                    )
                );
        }
        if (v == 4) {
            // Empire Band — double gold rail, three tips
            return
                string(
                    abi.encodePacked(
                        _crownPx("9", y0, "ffe08a"),
                        _crownPx("12", y0, "ffe08a"),
                        _crownPx("15", y0, "ffe08a"),
                        _crownBar("8", y1, "9", "f5d36b"),
                        _crownBar("8", y2, "9", "c9a227")
                    )
                );
        }
        if (v == 5) {
            // Arch Gate — raised side tips, soft center dip
            return
                string(
                    abi.encodePacked(
                        _crownPx("8", y0, "ffe08a"),
                        _crownPx("16", y0, "ffe08a"),
                        _crownPx("9", y1, "f5d36b"),
                        _crownPx("15", y1, "f5d36b"),
                        _crownBar("10", y1, "5", "e9bf52"),
                        _crownBar("9", y2, "7", "c9a227")
                    )
                );
        }
        if (v == 6) {
            // Broker Block — chunky center bar tip (king of the desk)
            return
                string(
                    abi.encodePacked(
                        _crownPx("8", y0, "ffe08a"),
                        _crownBar("11", y0, "3", "ffe08a"),
                        _crownPx("16", y0, "ffe08a"),
                        _crownBar("8", y1, "9", "f5d36b"),
                        _crownBar("9", y2, "7", "e9bf52")
                    )
                );
        }
        // 0 Classic Tri — odd band + tips @ 9/12/15
        return
            string(
                abi.encodePacked(
                    _crownPx("9", y0, "ffe08a"),
                    _crownPx("12", y0, "ffe08a"),
                    _crownPx("15", y0, "ffe08a"),
                    _crownBar("8", y1, "9", "f5d36b"),
