    /// @notice Centered crowns — band matches hair top (x=7 w=10); ruby straddles midline (x=11–12).
    /// 0 Tri Gold · 1 Tri Ruby · 2 Five Ruby · 3 Tiara Ruby · 4 Empire Ruby · 5 Arch Ruby · 6 Block Ruby
    function _svgCrownCentered(uint8 v, bool bald) internal pure returns (string memory) {
        string memory y0 = bald ? "1" : "0";
        string memory y1 = bald ? "2" : "1";
        string memory y2 = bald ? "3" : "2";
        string memory rail =
            string(
                abi.encodePacked(_crownBar("7", y1, "10", "f5d36b"), _crownBar("8", y2, "8", "e9bf52"))
            );
        if (v == 0) {
            return
                string(
                    abi.encodePacked(
                        _crownPx("8", y0, "ffe08a"),
                        _crownBar("11", y0, "2", "ffe08a"),
                        _crownPx("15", y0, "ffe08a"),
                        rail
                    )
                );
        }
        if (v == 1) {
            // Tri Ruby — favorite ruby accent, hair-centered (inlay after rail so it sits on band)
            return
                string(
                    abi.encodePacked(
                        _crownPx("8", y0, "ffe08a"),
                        _crownBar("11", y0, "2", "c62828"),
                        _crownPx("15", y0, "ffe08a"),
                        rail,
                        _crownBar("11", y1, "2", "ffe08a")
                    )
                );
        }
        if (v == 2) {
            return
                string(
                    abi.encodePacked(
                        _crownPx("8", y0, "ffe08a"),
                        _crownPx("10", y0, "ffe08a"),
                        _crownBar("11", y0, "2", "c62828"),
                        _crownPx("13", y0, "ffe08a"),
                        _crownPx("15", y0, "ffe08a"),
                        rail
                    )
                );
        }
        if (v == 3) {
            return
                string(
                    abi.encodePacked(
                        _crownPx("9", y0, "ffe08a"),
                        _crownBar("11", y0, "2", "c62828"),
                        _crownPx("14", y0, "ffe08a"),
                        _crownBar("8", y1, "8", "f5d36b"),
                        _crownBar("9", y2, "6", "e9bf52")
                    )
                );
        }
        if (v == 4) {
            return
                string(
                    abi.encodePacked(
                        _crownPx("8", y0, "ffe08a"),
                        _crownBar("11", y0, "2", "c62828"),
                        _crownPx("15", y0, "ffe08a"),
                        _crownBar("7", y1, "10", "f5d36b"),
                        _crownBar("7", y2, "10", "c9a227")
                    )
                );
        }
        if (v == 5) {
            return
                string(
                    abi.encodePacked(
                        _crownPx("7", y0, "ffe08a"),
                        _crownPx("16", y0, "ffe08a"),
                        _crownPx("8", y1, "f5d36b"),
                        _crownPx("15", y1, "f5d36b"),
                        _crownBar("11", y0, "2", "c62828"),
                        _crownBar("9", y1, "2", "e9bf52"),
                        _crownBar("13", y1, "2", "e9bf52"),
                        _crownBar("8", y2, "8", "c9a227")
                    )
                );
        }
        return
